import CategoryIcon from 'assets/icons/category.svg';
import ConnectionCreativityIcon from 'assets/icons/connection-creativity.svg';
import ConsumerIcon from 'assets/icons/consumer.svg';
import InnovationIcon from 'assets/icons/innovation.svg';
import PortfolioBrandIcon from 'assets/icons/portfolio-brand.svg';
import TradeExecutionIcon from 'assets/icons/trade-execution.svg';
import ValueCreationIcon from 'assets/icons/value-creation.svg';

import { EmptyType, ViewTypes } from '../domain';

// Pillars View
export const TRAININGS_VIEW: ViewTypes = 'Trainings View';
export const PILLARS_VIEW: ViewTypes = 'Pillars View';

// Empty Component
export const COMING_SOON_TYPE: EmptyType = 'coming-soon';
export const NO_DATA_TYPE: EmptyType = 'no-data';
export const SEARCH_EMPTY_TYPE: EmptyType = 'search-empty';

// Pillars View Styles
export const pillarStyles = {
  category: {
    background: '#FFD0B2',
    icon: CategoryIcon,
  },
  consumer: {
    background: '#FFEBA8',
    icon: ConsumerIcon,
  },
  'portfolio-brand': {
    background: '#CAFACA',
    icon: PortfolioBrandIcon,
  },
  innovation: {
    background: '#BAE3FF',
    icon: InnovationIcon,
  },
  'connection-creativity': {
    background: '#C3F7FA',
    icon: ConnectionCreativityIcon,
  },
  'trade-execution': {
    background: '#E3D7F5',
    icon: TradeExecutionIcon,
  },
  'value-creation': {
    background: '#FFC9C9',
    icon: ValueCreationIcon,
  },
};
